function renderHistory(root,history){if(!Array.isArray(history)||!history.length){root.replaceChildren(el('p','История измерений пока пуста.'));return;}const table=el('table'),thead=el('thead'),head=el('tr');for(const label of ['Измерено','Принято','Заряд','Напряжение','Ток','Мощность','Максимальная температура'])head.append(el('th',label));thead.append(head);const tbody=el('tbody');for(const item of history){const t=item.telemetry||{},temperatures=Array.isArray(t.temperaturesC)?t.temperaturesC.filter(Number.isFinite):[],max=temperatures.length?Math.max(...temperatures):null,row=el('tr');for(const value of [date(item.measuredAt),date(item.receivedAt),number(t.socPercent,1,'%'),number(t.voltageV,2,' В'),signedCurrent(t.currentA),number(Number.isFinite(t.powerW)?Math.abs(t.powerW):null,0,' Вт'),number(max,1,' °C')])row.append(el('td',value));tbody.append(row);}table.append(thead,tbody);root.replaceChildren(table);}
