async function refresh(){if(busy||document.hidden)return;busy=true;try{const data=await api('battery-state');render(data);status.textContent=`Обновлено ${new Date(data.now||Date.now()).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow'})}.`;}catch(error){status.textContent=error.message;if(error.status===401){$('#battery-login').hidden=false;list.replaceChildren();cards.clear();groups.clear();}else if(error.status===403)status.textContent='Доступ к состоянию аккумуляторов есть только у администратора.';}finally{busy=false;}}
