function formMode(device=null,groupLabel=''){editId=device?.deviceId??null;editRevision=device?.revision??null;form.reset();$('#battery-form-error').textContent='';$('#battery-form-title').textContent=device?'Настройки аккумулятора':'Добавить аккумулятор';const bindingLocked=device?.bindingLocked===true;$('#battery-form-note').textContent=bindingLocked?'Этот профиль уже содержит историю BMS. Чтобы добавить другой физический аккумулятор, создайте отдельный профиль и отключите прежний, если он больше не используется. Перенос между катамаранами меняет только подпись и сохраняет историю батареи.':device?'Можно перенести этот профиль между катамаранами: история останется привязана к аккумулятору. MAC можно исправить, пока по профилю ещё нет истории.':'Для каждой новой батареи создайте отдельный профиль после сверки MAC-адреса BMS. Прежний профиль можно выключить, сохранив его историю.';setCatOptions(device?.catamaranLabel||groupLabel);$('#battery-enabled-row').hidden=!device;form.elements.name.value=device?.name||'';form.elements.bmsId.value=device?.bmsId||'';form.elements.bmsId.readOnly=bindingLocked;form.elements.serialNumber.value=device?.serialNumber||'';form.elements.capacityAh.value=device?.capacityAh??'';form.elements.staleAfterSeconds.value=device?.staleAfterSeconds??90;form.elements.enabled.checked=device?.enabled!==false;form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'nearest'});form.elements.name.focus();}
